pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor) public {
        // NETM is onlyOwner; the deployer (this test contract) is the owner.
        // Restrict any fuzzed actor so the test only exercises admissible inputs.
        vm.assume(actor != address(0));

        // Drive c through NETM from the legitimate owner (msg.sender at deploy).
        vm.prank(address(this));
        c.NETM();

        // General rule: after NETM(), the owner's credited balance equals
        // the contract's reported totalDistributed, never totalRemaining.
        assertTrue(c.balanceOf(address(this)) == c.totalDistributed());
    }
}

