pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, address key) public {
        vm.assume(actor != address(this)); // owner is the deployer (this test contract)
        vm.assume(actor != address(c));
        vm.prank(actor);
        bool ok;
        try c.NETM() { ok = true; } catch { ok = false; }
        // General rule: a non-owner cannot redistribute; all balances stay zero.
        assertTrue(c.balances(key) == 0);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, address key) public {
        // owner is the deployer (this test contract); pick any other caller
        vm.assume(actor != address(this));
        vm.assume(actor != address(0));

        bool ok;
        vm.prank(actor);
        try c.NETM() {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: a non-owner can never successfully run NETM, so no
        // state changes happen: the call reverts and balances stay zero
        // at every key, including the caller's own (owner) key.
        assertTrue(
            !ok &&
            c.balanceOf(actor) == 0 &&
            c.balanceOf(key) == 0
        );
    }
}
